height=\"32\" rx=\"5\" fill=\"#33475B\"/><rect x=\"-17\" y=\"-80\" width=\"34\" height=\"54\" rx=\"12\" fill=\"#2F8F4E\"/><path d=\"M-14 -70 L -24 -38\" stroke=\"#2F8F4E\" stroke-width=\"9\" stroke-linecap=\"round\"/><path d=\"M14 -70 L 26 -40\" stroke=\"#2F8F4E\" stroke-width=\"9\" stroke-linecap=\"round\"/><circle cx=\"0\" cy=\"-96\" r=\"15\" fill=\"#C98B5E\"/></g><g transform=\"translate(1040 640) scale(1.00)\"><rect x=\"-13\" y=\"-30\" width=\"11\" height=\"32\" rx=\"5\" fill=\"#33475B\"/><rect x=\"2\" y=\"-30\" width=\"11\" height=\"32\" rx=\"5\" fill=\"#33475B\"/><rect x=\"-17\" y=\"-80\" width=\"34\" height=\"54\" rx=\"12\" fill=\"#3C7DC4\"/><path d=\"M-14 -70 L -24 -38\" stroke=\"#3C7DC4\" stroke-width=\"9\" stroke-linecap=\"round\"/><path d=\"M14 -70 L 26 -40\" stroke=\"#3C7DC4\" stroke-width=\"9\" stroke-linecap=\"round\"/><circle cx=\"0\" cy=\"-96\" r=\"15\" fill=\"#C98B5E\"/></g></svg>','2026-11-20 17:07:32');
INSERT INTO `messages` VALUES
(1,'Andi Pratama','andi@contoh.id',NULL,'Kunjungan studi banding','Selamat siang, kami dari kelompok tani desa tetangga ingin studi banding tentang beras organik. Kapan waktu yang tepat?',0,'2026-11-20 17:07:32'),
(2,'Maya Sari',NULL,'081377788899','Syarat surat domisili','Mohon info syarat membuat surat keterangan domisili untuk keperluan kerja.',1,'2026-11-20 17:07:32');
INSERT INTO `news` VALUES
(1,'Gotong Royong Bersihkan Lingkungan Desa','gotong-royong-bersihkan-lingkungan-desa','Berita',1,'Ratusan warga dari seluruh RT turun bersama membersihkan fasilitas umum dan lingkungan sekitar menjelang musim hujan. Kegiatan dimulai pukul 07.00 WIB dan selesai menjelang siang.','Ratusan warga dari seluruh RT turun bersama membersihkan fasilitas umum dan lingkungan sekitar menjelang musim hujan. Kegiatan dimulai pukul 07.00 WIB dan selesai menjelang siang.\n\nSelain membersihkan saluran air, warga juga merapikan bahu jalan, memangkas ranting pohon yang membahayakan, dan mengumpulkan sampah plastik untuk bank sampah Karang Taruna.\n\nKepala Desa Budi Santoso berterima kasih kepada seluruh warga dan berharap kebiasaan Jumat Bersih terus terjaga.',8,'Admin Desa','2026-11-08','Terbit','2026-11-20 17:07:32'),
(2,'Program Tanam Pohon untuk Desa Hijau','program-tanam-pohon-untuk-desa-hijau','Kegiatan',0,'Warga bersama perangkat desa menanam 1.200 bibit pohon di sepanjang jalan poros desa dan bantaran Sungai Kenanga. Bibit yang ditanam meliputi trembesi, mahoni, durian, dan petai.','Warga bersama perangkat desa menanam 1.200 bibit pohon di sepanjang jalan poros desa dan bantaran Sungai Kenanga. Bibit yang ditanam meliputi trembesi, mahoni, durian, dan petai.\n\nSetiap RT mendapat tanggung jawab merawat bibit di wilayahnya selama satu tahun.\n\nWarga yang ingin ikut mengadopsi pohon bisa mendaftar di Kantor Desa pada jam pelayanan.',29,'Admin Desa','2026-11-10','Terbit','2026-11-20 17:07:32'),
(3,'Jadwal dan Jam Pelayanan Kantor Desa','jadwal-dan-jam-pelayanan-kantor-desa','Berita',0,'Pelayanan administrasi di Kantor Desa Marga Mulya dibuka Senin sampai Jumat, pukul 08.00 sampai 16.00 WIB. Sabtu, Minggu, dan hari libur nasional kantor tutup.','Pelayanan administrasi di Kantor Desa Marga Mulya dibuka Senin sampai Jumat, pukul 08.00 sampai 16.00 WIB. Sabtu, Minggu, dan hari libur nasional kantor tutup.\n\nWarga yang membutuhkan surat keterangan diharapkan membawa KTP dan Kartu Keluarga asli. Untuk pengaduan di luar jam kerja, gunakan layanan LaporDesa di website ini.\n\nTerima kasih atas perhatiannya.',17,'Admin Desa','2026-11-06','Terbit','2026-11-20 17:07:32'),
(4,'Pelatihan UMKM Digital untuk Warga','pelatihan-umkm-digital-untuk-warga','Berita',0,'Pelaku usaha lokal belajar memasarkan produk lewat media sosial dan marketplace di Balai Desa. Sebanyak 35 peserta belajar memotret produk dengan ponsel dan menulis deskripsi yang ','Pelaku usaha lokal belajar memasarkan produk lewat media sosial dan marketplace di Balai Desa. Sebanyak 35 peserta belajar memotret produk dengan ponsel dan menulis deskripsi yang menarik.\n\nPelatihan diselenggarakan BUMDes Marga Lestari bersama pendamping desa. Setiap peserta pulang dengan akun toko daring yang siap digunakan.\n\nPendampingan lanjutan dilakukan setiap bulan selama tiga bulan ke depan.',16,'Admin Desa','2026-10-28','Terbit','2026-11-20 17:07:32'),
(5,'Kerja Bakti Bersihkan Saluran Air','kerja-bakti-bersihkan-saluran-air','Kegiatan',0,'Seluruh RT ikut membersihkan saluran agar aman dari genangan. Lumpur dan sampah yang menyumbat drainase di RW 02 dan RW 03 berhasil diangkat.','Seluruh RT ikut membersihkan saluran agar aman dari genangan. Lumpur dan sampah yang menyumbat drainase di RW 02 dan RW 03 berhasil diangkat.\n\nPemerintah desa menyediakan alat dan konsumsi, sementara warga bergotong royong sejak pagi.\n\nWarga diimbau tidak membuang sampah ke saluran air agar tidak terjadi banjir saat hujan deras.',8,'Admin Desa','2026-10-20','Terbit','2026-11-20 17:07:32'),
(6,'Panen Raya Padi Musim Ini','panen-raya-padi-musim-ini','Berita',0,'Hasil panen meningkat berkat perbaikan irigasi. Kelompok tani mencatat rata-rata 5 ton gabah kering panen per hektare.','Hasil panen meningkat berkat perbaikan irigasi. Kelompok tani mencatat rata-rata 5 ton gabah kering panen per hektare.\n\nKenaikan hasil juga didukung penggunaan benih unggul dan pupuk organik buatan kelompok.\n\nSebagian hasil panen akan diolah menjadi beras organik kemasan oleh BUMDes.',15,'Admin Desa','2026-10-12','Terbit','2026-11-20 17:07:32'),
(7,'Pendataan Warga Tahun 2026','pendataan-warga-tahun-2026','Berita',0,'Petugas akan mendatangi tiap rumah untuk pendataan warga tahun 2026. Mohon siapkan Kartu Keluarga dan KTP seluruh anggota keluarga.','Petugas akan mendatangi tiap rumah untuk pendataan warga tahun 2026. Mohon siapkan Kartu Keluarga dan KTP seluruh anggota keluarga.\n\nPendataan berlangsung mulai 5 sampai 30 Oktober 2026 dan dilakukan oleh kader yang membawa surat tugas dari Pemerintah Desa.\n\nData yang terkumpul dipakai untuk perencanaan program desa dan bantuan sosial yang tepat sasaran.',18,'Admin Desa','2026-10-03','Terbit','2026-11-20 17:07:32'),
(8,'Festival Desa Marga Mulya 2026 Sukses Digelar','festival-desa-marga-mulya-2026-sukses-digelar','Berita',0,'Festival Desa Marga Mulya 2026 berlangsung meriah selama dua hari di Lapangan Desa, diisi pentas seni, lomba masak olahan pangan lokal, dan bazar 40 UMKM.','Festival Desa Marga Mulya 2026 berlangsung meriah selama dua hari di Lapangan Desa, diisi pentas seni, lomba masak olahan pangan lokal, dan bazar 40 UMKM.\n\nProduk yang paling diminati adalah beras organik, madu kelulut, dan anyaman warga.\n\nFestival tahun depan direncanakan menghadirkan lebih banyak paket wisata Sungai Kenanga.',6,'Admin Desa','2026-09-25','Terbit','2026-11-20 17:07:32'),
(9,'Posyandu Balita Rutin Bulan November','posyandu-balita-rutin-bulan-november','Kegiatan',0,'Posyandu di enam titik kembali membuka layanan penimbangan, imunisasi, dan pemberian makanan tambahan pada minggu kedua setiap bulan.','Posyandu di enam titik kembali membuka layanan penimbangan, imunisasi, dan pemberian makanan tambahan pada minggu kedua setiap bulan.\n\nOrang tua diimbau membawa buku KIA.\n\nJadwal lengkap dapat ditanyakan ke kader posyandu di masing-masing RW.',21,'Admin Desa','2026-09-15','Terbit','2026-11-20 17:07:32'),
(10,'Musyawarah Desa Rencana Kerja 2027','musyawarah-desa-rencana-kerja-2027','Organisasi',0,'BPD bersama pemerintah desa menggelar musyawarah untuk menyusun Rencana Kerja Pemerintah Desa tahun 2027.','BPD bersama pemerintah desa menggelar musyawarah untuk menyusun Rencana Kerja Pemerintah Desa tahun 2027.\n\nUsulan prioritas warga antara lain perbaikan jalan desa di RW 02, penambahan lampu penerangan jalan, dan pengembangan wisata Sungai Kenanga.\n\nHasil musyawarah akan dibahas lebih lanjut dalam penyusunan APBDes 2027.',22,'Admin Desa','2026-08-25','Terbit','2026-11-20 17:07:32'),
(11,'Jalan Usaha Tani Sepanjang 1,2 Km Selesai Dibeton','jalan-usaha-tani-sepanjang-1-2-km-selesai-dibeton','Berita',0,'Jalan usaha tani di RW 03 sepanjang 1,2 km kini sudah dibeton dan menghubungkan permukiman dengan area perkebunan.','Jalan usaha tani di RW 03 sepanjang 1,2 km kini sudah dibeton dan menghubungkan permukiman dengan area perkebunan.\n\nSebelumnya jalan sulit dilewati kendaraan pengangkut hasil panen saat musim hujan.\n\nPembangunan dibiayai dana desa 2026 dan dikerjakan secara padat karya oleh warga setempat.',10,'Admin Desa','2026-08-15','Terbit','2026-11-20 17:07:32'),
(12,'PKK Gelar Lomba Pekarangan Hijau','pkk-gelar-lomba-pekarangan-hijau','Organisasi',0,'Tim Penggerak PKK menggelar lomba pekarangan hijau antar-RT. Penilaian meliputi tanaman obat keluarga, sayuran, kebersihan, dan pengolahan sampah rumah tangga.','Tim Penggerak PKK menggelar lomba pekarangan hijau antar-RT. Penilaian meliputi tanaman obat keluarga, sayuran, kebersihan, dan pengolahan sampah rumah tangga.\n\nJuara pertama diraih RT 07 yang memanfaatkan pekarangan sempit dengan rak vertikal dan kolam ikan kecil.\n\nLomba ini menjadi bagian dari gerakan kemandirian pangan keluarga.',28,'Admin Desa','2026-08-05','Terbit','2026-11-20 17:07:32'),
(13,'Karang Taruna Bentuk Kepengurusan Baru','karang-taruna-bentuk-kepengurusan-baru','Organisasi',0,'Karang Taruna Desa Marga Mulya membentuk kepengurusan baru periode 2026–2029 melalui musyawarah anggota di Balai Desa.','Karang Taruna Desa Marga Mulya membentuk kepengurusan baru periode 2026–2029 melalui musyawarah anggota di Balai Desa.\n\nPengurus baru menyiapkan tiga program utama: sanggar seni, bank sampah, dan pelatihan keterampilan digital bagi pemuda.\n\nPemuda desa yang ingin bergabung bisa menghubungi pengurus melalui media sosial Karang Taruna.',23,'Admin Desa','2026-07-20','Terbit','2026-11-20 17:07:32');
